  "Zieh die Wanderschuhe an, mit Turnschuhen rutschst du.": "Βάλε τα ορειβατικά παπούτσια, με τα αθλητικά θα γλιστράς.",
  "Lauf die neuen Schuhe vorher ein, sonst gibt es Blasen.": "Στρώσε πρώτα τα καινούργια παπούτσια, αλλιώς θα βγάλεις φουσκάλες.",
  "Der Wanderweg ist rot-weiß markiert.": "Το μονοπάτι έχει κόκκινη και άσπρη σήμανση.",
  "An der Markierung halten wir uns links.": "Στη σήμανση κρατάμε αριστερά.",
