  "Trink regelmäßig, nicht erst bei Durst.": "Πίνε νερό τακτικά, όχι μόνο όταν διψάς.",
  "Die Abkürzung war natürlich keine.": "Η συντόμευση, φυσικά, δεν ήταν καθόλου συντόμευση.",
