  "Meine Blase meldet sich — hast du ein Pflaster dabei?": "Η φουσκάλα μου άρχισε να πονάει — έχεις μαζί σου κανένα τσιρότο;",
  "Kurz vor dem Gipfel wird es noch mal steil.": "Λίγο πριν από την κορυφή ο δρόμος ανηφορίζει ξανά απότομα.",
  "Geschafft — da vorne ist das Gipfelkreuz!": "Τα καταφέραμε — εκεί μπροστά είναι ο σταυρός της κορυφής!",
  "Am Gipfelkreuz wird erst mal fotografiert.": "Στον σταυρό της κορυφής πρώτα βγάζουμε φωτογραφίες.",
  "Das Gipfelbuch tragen wir uns natürlich ein.": "Φυσικά γράφουμε τα ονόματά μας στο βιβλίο της κορυφής.",
  "Die Aussicht entschädigt für jeden Schweißtropfen.": "Η θέα αξίζει κάθε σταγόνα ιδρώτα.",
