  "Der Abstieg geht in die Knie.": "Στην κατάβαση πονάνε τα γόνατα.",
  "Bergab bin ich langsamer als bergauf.": "Στην κατηφόρα πάω πιο αργά από ό,τι στην ανηφόρα.",
  "Mit Stöcken ist der Abstieg halb so anstrengend.": "Με μπαστούνια η κατάβαση είναι μισή κούραση.",
  "Unten im Tal kehren wir ein.": "Κάτω στην κοιλάδα θα κάτσουμε κάπου να φάμε.",
  "Nach der Tour schmeckt das Radler wie nichts sonst.": "Μετά τη διαδρομή, η μπίρα με λεμονάδα δεν συγκρίνεται με τίποτα.",
  "Morgen spüre ich jeden Muskel, ich weiß es jetzt schon.": "Αύριο θα πονάει και ο τελευταίος μυς μου, το ξέρω από τώρα.",
  "Und trotzdem: nächsten Monat wieder.": "Κι όμως: τον άλλο μήνα πάλι.",
  "The shortcut": "Ο σύντομος δρόμος",
  "Laut Karte sparen wir hier zwanzig Minuten.": "Σύμφωνα με τον χάρτη, από εδώ κερδίζουμε είκοσι λεπτά.",
  "Der Weg sieht aber steil aus.": "Το μονοπάτι όμως φαίνεται απότομο.",
  "Komm, wir sind doch keine Anfänger.": "Έλα, δεν είμαστε δα και αρχάριοι.",
  "Das sagst du jedes Mal — und jedes Mal verlaufen wir uns.": "Αυτό λες κάθε φορά — και κάθε φορά χανόμαστε.",
  "At the top": "Στην κορυφή",
  "Geschafft! Da ist das Gipfelkreuz.": "Τα καταφέραμε! Να ο σταυρός της κορυφής.",
