  "Trag uns ins Gipfelbuch ein.": "Γράψε μας στο βιβλίο της κορυφής.",
  "Mach ich. Und dann genießen wir einfach die Aussicht.": "Έγινε. Και μετά απλώς απολαμβάνουμε τη θέα.",
  "Ich möchte dieses Rezept einlösen.": "Θα ήθελα να εκτελέσω αυτή τη συνταγή.",
