  "Gibt es das auch rezeptfrei?": "Υπάρχει και χωρίς συνταγή;",
  "Der Arzt hat mir etwas Stärkeres verschrieben.": "Ο γιατρός μού έγραψε κάτι πιο δυνατό.",
  "Wir hätten da ein günstigeres Generikum — gleicher Wirkstoff.": "Έχουμε κι ένα φθηνότερο γενόσημο — με την ίδια δραστική ουσία.",
  "Das Generikum wirkt genauso, kostet aber die Hälfte.": "Το γενόσημο κάνει την ίδια δουλειά, αλλά κοστίζει τα μισά.",
  "Die Apothekerin hat mich super beraten.": "Η φαρμακοποιός με συμβούλεψε πάρα πολύ καλά.",
