  "Nehmen Sie schon andere Medikamente?": "Παίρνετε ήδη άλλα φάρμακα;",
  "Ich frag wegen der Wechselwirkungen — sicher ist sicher.": "Το ρωτάω για τις αλληλεπιδράσεις — καλού κακού.",
  "Ich frage wegen der Wechselwirkungen — sicher ist sicher.": "Το ρωτάω για τις αλληλεπιδράσεις — καλού κακού.",
