  "Für das Schließfach brauchst du ein Euro-Stück — wie beim Einkaufswagen.": "Για το ντουλαπάκι χρειάζεσαι ένα κέρμα του ενός ευρώ — όπως στο καρότσι του σούπερ μάρκετ.",
