  "Das hast du wirklich gut gemacht.": "Το έκανες πραγματικά πολύ καλά.",
  "Ich finde es beeindruckend, wie ruhig du geblieben bist.": "Με εντυπωσιάζει πώς κράτησες την ψυχραιμία σου.",
  "Danke, dass du daran gedacht hast — das war aufmerksam.": "Ευχαριστώ που το σκέφτηκες — πολύ ευγενικό εκ μέρους σου.",
