  "In Deutschland wird eher sparsam gelobt.": "Στη Γερμανία επαινούν μάλλον με φειδώ.",
  "Kein Tadel ist hier schon fast ein Lob.": "Εδώ, το να μη σε επικρίνουν είναι σχεδόν έπαινος.",
  "Deshalb freut man sich umso mehr wenn doch mal eins kommt.": "Γι' αυτό, όταν έρθει τελικά ένας, χαίρεσαι ακόμα περισσότερο.",
  "Deshalb freut man sich umso mehr, wenn doch mal eins kommt.": "Γι' αυτό, όταν έρθει τελικά ένας, χαίρεσαι ακόμα περισσότερο.",
