  "Welche Wandfarbe nehmen wir?": "Τι χρώμα τοίχου θα πάρουμε;",
  "An der Wand sieht die Farbe ganz anders aus als auf der Karte.": "Στον τοίχο το χρώμα φαίνεται τελείως διαφορετικό απ' ό,τι στο χρωματολόγιο.",
