  "Ich kann morgen nicht, ich habe nämlich einen Termin beim Zahnarzt.": "Αύριο δεν μπορώ, έχω βλέπεις ραντεβού στον οδοντίατρο.",
  "Das wird knapp, wir haben nämlich erst die Hälfte geschafft.": "Θα είναι οριακό, έχουμε κάνει βλέπεις μόλις τα μισά.",
  "Er kennt den Weg, er ist nämlich hier aufgewachsen.": "Ξέρει τον δρόμο, μεγάλωσε βλέπεις εδώ.",
  "Frag lieber Anna, sie hat das nämlich schon mal gemacht.": "Ρώτα καλύτερα την Άννα, το έχει ξανακάνει βλέπεις.",
  "Wir müssen leise sein, das Baby schläft nämlich endlich.": "Πρέπει να κάνουμε ησυχία, το μωρό βλέπεις κοιμήθηκε επιτέλους.",
