  "Kein Problem. Ehrlich gesagt war ich auch müde.": "Κανένα πρόβλημα. Για να πω την αλήθεια, κι εγώ είχα κουραστεί.",
  "Dann holen wir es nächste Woche nach.": "Τότε το κανονίζουμε για την άλλη εβδομάδα.",
  "Running late": "Θα αργήσω",
