  "Im Zweifel haftest du privat, und das kann teuer werden.": "Σε περίπτωση αμφιβολίας ευθύνεσαι προσωπικά, και αυτό μπορεί να σου κοστίσει ακριβά.",
  "Ich hab dem Nachbarn aus Versehen die Scheibe kaputt gemacht — das übernimmt die Haftpflicht.": "Έσπασα κατά λάθος το τζάμι του γείτονα — αυτό το καλύπτει η αστική ευθύνη.",
  "Ich habe dem Nachbarn aus Versehen die Scheibe kaputt gemacht — das übernimmt die Haftpflicht.": "Έσπασα κατά λάθος το τζάμι του γείτονα — αυτό το καλύπτει η αστική ευθύνη.",
  "Unterschätz nicht, wie schnell so ein Schaden in die Tausende geht.": "Μην υποτιμάς πόσο γρήγορα μια τέτοια ζημιά φτάνει τις χιλιάδες.",
  "Bei der Kfz-Versicherung zählt deine Schadenfreiheitsklasse.": "Στην ασφάλιση αυτοκινήτου μετράει το ιστορικό ζημιών σου.",
  "Nach dem Unfall stufen sie dich hoch.": "Μετά το ατύχημα θα σου ανεβάσουν το ασφάλιστρο.",
  "Teilkasko oder Vollkasko — was lohnt sich bei dem Auto noch?": "Πυρός-κλοπής ή μικτή — τι συμφέρει ακόμα γι' αυτό το αμάξι;",
  "Reporting the water damage": "Δήλωση ζημιάς από νερό",
  "Ich möchte einen Schaden melden. Unsere Waschmaschine ist ausgelaufen.": "Θα ήθελα να δηλώσω μια ζημιά. Το πλυντήριό μας έτρεξε νερά.",
  "Ist der Boden beschädigt?": "Έχει πάθει ζημιά το πάτωμα;",
  "Ja, das Laminat wirft schon Wellen.": "Ναι, το λαμινέιτ έχει ήδη φουσκώσει.",
  "Schicken Sie uns Fotos, dann prüfen wir die Erstattung.": "Στείλτε μας φωτογραφίες και θα εξετάσουμε την αποζημίωση.",
  "Which insurance do I need?": "Ποια ασφάλεια χρειάζομαι;",
  "Brauche ich wirklich eine Haftpflicht?": "Χρειάζομαι στ' αλήθεια ασφάλιση αστικής ευθύνης;",
  "Brauch ich wirklich eine Haftpflicht?": "Χρειάζομαι στ' αλήθεια ασφάλιση αστικής ευθύνης;",
  "Unbedingt. Die paar Euro im Monat lohnen sich.": "Οπωσδήποτε. Αξίζουν τα λίγα ευρώ τον μήνα.",
  "Und was ist mit Hausrat?": "Και τι γίνεται με την οικοσκευή;",
  "Kommt drauf an, was deine Sachen wert sind.": "Εξαρτάται από το πόσο αξίζουν τα πράγματά σου.",
  "Kommt drauf an was deine Sachen wert sind.": "Εξαρτάται από το πόσο αξίζουν τα πράγματά σου.",
  "einreichen": "υποβάλλω",
  "Mein Personalausweis läuft nächsten Monat ab.": "Η ταυτότητά μου λήγει τον επόμενο μήνα.",
  "Den neuen Ausweis müssen Sie persönlich beantragen.": "Για τη νέα ταυτότητα πρέπει να κάνετε αίτηση αυτοπροσώπως.",
  "Bringen Sie ein aktuelles Passfoto mit.": "Φέρτε μια πρόσφατη φωτογραφία τύπου διαβατηρίου.",
  "Ohne Termin brauchen Sie hier gar nicht erst zu kommen.": "Χωρίς ραντεβού δεν έχει νόημα καν να έρθετε εδώ.",
  "Die Online-Termine sind auf Wochen ausgebucht — probier es morgens um acht.": "Τα online ραντεβού είναι κλεισμένα για εβδομάδες — δοκίμασε στις οχτώ το πρωί.",
  "Ziehen Sie eine Wartenummer und nehmen Sie Platz.": "Πάρτε αριθμό προτεραιότητας και καθίστε.",
  "Ich war heute drei Stunden auf dem Amt.": "Σήμερα πέρασα τρεις ώρες στην υπηρεσία.",
  "Man wird gern von einem Amt zum nächsten geschickt.": "Συνήθως σε γυρνάνε από τη μια υπηρεσία στην άλλη.",
  "Zum Glück ging heute alles schneller als gedacht.": "Ευτυχώς σήμερα όλα έγιναν πιο γρήγορα απ' ό,τι περίμενα.",
  "Welche Unterlagen muss ich mitbringen?": "Ποια δικαιολογητικά πρέπει να φέρω;",
  "Füllen Sie das Formular am besten schon zu Hause aus.": "Καλύτερα να συμπληρώσετε το έντυπο από το σπίτι.",
  "Hier fehlt noch eine Unterschrift, direkt unter dem Datum.": "Εδώ λείπει ακόμα μια υπογραφή, ακριβώς κάτω από την ημερομηνία.",
  "Brauchen Sie das Original oder reicht eine Kopie?": "Χρειάζεστε το πρωτότυπο ή αρκεί ένα αντίγραφο;",
  "Die Kopie muss beglaubigt sein.": "Το αντίγραφο πρέπει να είναι επικυρωμένο.",
  "Die Beglaubigung bekommen Sie im Bürgerbüro für ein paar Euro.": "Την επικύρωση μπορείτε να την κάνετε στο Bürgerbüro με λίγα ευρώ.",
  "Ich stelle Ihnen eine Vollmacht aus, dann kann meine Frau das abholen.": "Θα σας δώσω μια εξουσιοδότηση, για να μπορεί να το παραλάβει η γυναίκα μου.",
  "Mit der Vollmacht dürfen Sie die Papiere für ihn abholen.": "Με την εξουσιοδότηση μπορείτε να παραλάβετε τα χαρτιά για λογαριασμό του.",
  "Ohne Stempel ist das Formular nicht gültig.": "Χωρίς σφραγίδα το έντυπο δεν ισχύει.",
  "Dafür sind wir nicht zuständig, das macht das Landratsamt.": "Δεν είμαστε αρμόδιοι γι' αυτό, το χειρίζεται το Landratsamt.",
  "Der Antrag ist durch, Sie bekommen Post von uns.": "Η αίτηση εγκρίθηκε, θα λάβετε επιστολή από εμάς.",
  "Den Bescheid schicken wir Ihnen innerhalb von vier Wochen zu.": "Την απόφαση θα σας τη στείλουμε μέσα σε τέσσερις εβδομάδες.",
  "Gegen den Bescheid können Sie Widerspruch einlegen.": "Κατά της απόφασης μπορείτε να υποβάλετε ένσταση.",
  "Die Widerspruchsfrist beträgt einen Monat.": "Η προθεσμία για ένσταση είναι ένας μήνας.",
  "Reichen Sie die fehlenden Unterlagen bitte innerhalb von vierzehn Tagen nach.": "Παρακαλούμε προσκομίστε τα δικαιολογητικά που λείπουν μέσα σε δεκατέσσερις ημέρες.",
  "Wir möchten standesamtlich heiraten — welche Unterlagen brauchen wir?": "Θέλουμε να κάνουμε πολιτικό γάμο — ποια δικαιολογητικά χρειαζόμαστε;",
  "Für die Anmeldung zur Hochzeit brauchen Sie Ihre Geburtsurkunde.": "Για τη δήλωση του γάμου χρειάζεστε τη ληξιαρχική πράξη γέννησής σας.",
  "Meine Geburtsurkunde muss erst übersetzt und beglaubigt werden.": "Η ληξιαρχική πράξη γέννησής μου πρέπει πρώτα να μεταφραστεί και να επικυρωθεί.",
  "Als Nachweis reicht die Meldebescheinigung.": "Ως αποδεικτικό αρκεί η βεβαίωση μόνιμης κατοικίας.",
  "Renewing the ID card": "Ανανέωση ταυτότητας",
  "Mein Ausweis ist abgelaufen. Was brauche ich für den neuen?": "Η ταυτότητά μου έληξε. Τι χρειάζομαι για την καινούργια;",
