  "Etwa drei Wochen. Zum Abholen reicht dann eine Vollmacht.": "Περίπου τρεις εβδομάδες. Για την παραλαβή αρκεί μετά μια εξουσιοδότηση.",
  "Registering to get married": "Δήλωση γάμου",
  "Wir möchten heiraten und uns beim Standesamt anmelden.": "Θέλουμε να παντρευτούμε και να κάνουμε τη δήλωση στο ληξιαρχείο.",
  "Herzlichen Glückwunsch! Bringen Sie beide Ihre Geburtsurkunden mit.": "Συγχαρητήρια! Να φέρετε και οι δύο τις ληξιαρχικές πράξεις γέννησής σας.",
  "Meine ist auf Englisch — ist das ein Problem?": "Η δική μου είναι στα αγγλικά — είναι πρόβλημα αυτό;",
