  "Ich trage es mir gleich in den Kalender ein.": "Το σημειώνω αμέσως στο ημερολόγιο.",
  "Ohne Kalendereintrag vergesse ich es garantiert.": "Αν δεν το σημειώσω στο ημερολόγιο, σίγουρα θα το ξεχάσω.",
  "Bei mir klappt es doch heute — bist du noch frei?": "Τελικά μπορώ σήμερα — έχεις ακόμα χρόνο;",
