  "Tatsächlich ja. Mein Termin ist ausgefallen.": "Βασικά ναι. Το ραντεβού μου ακυρώθηκε.",
  "Dann ziehen wir unser Essen einfach vor.": "Τότε ας φέρουμε το φαγητό μας νωρίτερα.",
  "Perfekt. Um sieben im Üblichen?": "Τέλεια. Στις εφτά στο γνωστό μέρος;",
  "das Meeting": "η σύσκεψη",
