  "Wähl dich am besten fünf Minuten früher ein.": "Καλύτερα να συνδεθείς πέντε λεπτά νωρίτερα.",
  "Der Link zur Videokonferenz steht im Kalendereintrag.": "Ο σύνδεσμος για την τηλεδιάσκεψη είναι στο ημερολόγιο, μέσα στην πρόσκληση.",
  "Hört ihr mich? Seht ihr mein Bild?": "Με ακούτε; Με βλέπετε;",
  "Du bist auf stumm!": "Είσαι σε σίγαση!",
  "Sorry, ich war stummgeschaltet.": "Σόρι, ήμουν σε σίγαση.",
