  "Ich teile kurz meinen Bildschirm.": "Θα μοιραστώ για λίγο την οθόνη μου.",
  "Wir sehen noch dein Postfach, nicht die Präsentation.": "Βλέπουμε ακόμα τα εισερχόμενά σου, όχι την παρουσίαση.",
  "Geh mal eine Folie zurück, bitte.": "Γύρνα μια διαφάνεια πίσω, σε παρακαλώ.",
  "Einer nach dem anderen, sonst versteht man nichts.": "Ένας ένας, αλλιώς δεν καταλαβαίνει κανείς τίποτα.",
  "Entschuldigung, ich wollte dich nicht unterbrechen — sprich weiter.": "Συγγνώμη, δεν ήθελα να σε διακόψω — συνέχισε.",
  "Bitte alle stummschalten, die gerade nicht sprechen.": "Όσοι δεν μιλάτε αυτή τη στιγμή, κάντε σίγαση, παρακαλώ.",
