  "Dein virtueller Hintergrund flackert ein bisschen.": "Το εικονικό σου φόντο τρεμοπαίζει λίγο.",
  "Im Hintergrund läuft bei mir gleich die Waschmaschine los — Entschuldigung im Voraus.": "Σε λίγο θα ξεκινήσει το πλυντήριο στο βάθος — συγγνώμη από τώρα.",
